import Foundation

/// Search ordering on Hacker News.
public enum SearchSort: String, Sendable, Hashable, Codable {
    /// Algolia's relevance ranking (`/search`).
    case relevance

    /// Newest first (`/search_by_date`).
    case date
}

/// A semantic search request. Transport-specific tag and numeric filter syntax
/// is generated by the adapter.
public struct SearchQuery: Sendable, Hashable {
    public var terms: String
    public var kinds: Set<ItemKind>
    public var author: UserID?
    public var storyID: ItemID?
    public var sort: SearchSort
    public var page: PageRequest
    public var createdAfter: Date?
    public var createdBefore: Date?
    public var minimumScore: Int?
    public var minimumComments: Int?

    public init(
        terms: String = "",
        kinds: Set<ItemKind> = [.story],
        author: UserID? = nil,
        storyID: ItemID? = nil,
        sort: SearchSort = .relevance,
        page: PageRequest = .default,
        createdAfter: Date? = nil,
        createdBefore: Date? = nil,
        minimumScore: Int? = nil,
        minimumComments: Int? = nil
    ) {
        self.terms = terms
        self.kinds = kinds
        self.author = author
        self.storyID = storyID
        self.sort = sort
        self.page = page
        self.createdAfter = createdAfter
        self.createdBefore = createdBefore
        self.minimumScore = minimumScore
        self.minimumComments = minimumComments
    }
}

/// A partial item returned by search. Search hits are projections; use
/// `FetchItem` when the full item is needed.
public struct SearchHit: Sendable, Hashable, Identifiable {
    public let id: ItemID
    public let kind: ItemKind
    public let author: UserID?
    public let createdAt: Date
    public let title: HTMLText?
    public let url: URL?
    public let text: HTMLText?
    public let score: Int?
    public let commentCount: Int?
    public let storyID: ItemID?
    public let storyTitle: HTMLText?
    public let parentID: ItemID?

    public init(
        id: ItemID,
        kind: ItemKind,
        author: UserID? = nil,
        createdAt: Date,
        title: HTMLText? = nil,
        url: URL? = nil,
        text: HTMLText? = nil,
        score: Int? = nil,
        commentCount: Int? = nil,
        storyID: ItemID? = nil,
        storyTitle: HTMLText? = nil,
        parentID: ItemID? = nil
    ) {
        self.id = id
        self.kind = kind
        self.author = author
        self.createdAt = createdAt
        self.title = title
        self.url = url
        self.text = text
        self.score = score
        self.commentCount = commentCount
        self.storyID = storyID
        self.storyTitle = storyTitle
        self.parentID = parentID
    }
}

public struct SearchResults: Sendable, Hashable {
    public let hits: [SearchHit]
    public let totalHits: Int
    public let page: Int
    public let pageCount: Int
    public let query: String

    public var hasMore: Bool { page + 1 < pageCount }

    public init(
        hits: [SearchHit],
        totalHits: Int,
        page: Int,
        pageCount: Int,
        query: String
    ) {
        self.hits = hits
        self.totalHits = totalHits
        self.page = page
        self.pageCount = pageCount
        self.query = query
    }
}
